def LNr(X): X=X-X.mean(1,keepdims=True); return X/X.std(1,keepdims=True)
X = LNr(5*F['mean_hidden_L9']+F['cls_hidden_L9'])[:,KEEP]
def pivchol(Z, kfun, m):
    n=len(Z); d=np.array([kfun(Z[i:i+1],Z[i:i+1])[0,0] for i in range(n)]); L=np.zeros((m,n)); piv=[]
    for j in range(m):
        i=int(np.argmax(d)); piv.append(i)
        kc=kfun(Z,Z[i:i+1])[:,0]; l=(kc-L[:j].T@L[:j,i])/np.sqrt(d[i]); L[j]=l; d=d-l**2; d[i]=-np.inf
    return np.array(piv)
def kmeans(Z,k,it=15,seed=0):
    rng=np.random.default_rng(seed); C=Z[rng.choice(len(Z),k,replace=False)]
    for _ in range(it):
        a=np.argmax(Z@C.T-0.5*(C**2).sum(1)[None],1)
        for j in range(k):
            if (a==j).any(): C[j]=Z[a==j].mean(0)
    return C
def sor_cv(X,y,nunits=768,gamma=0.4,lams=(1e-3,1e-2),seeds=(0,1,2),sel='random'):
    n=len(y); res={l:0 for l in lams}
    f=lambda A,B: np.exp(2*gamma*(A@B.T-1))
    for s in seeds:
        for te in folds(n,5,s,y):
            tr=np.setdiff1d(np.arange(n),te)
            mu=X[tr].mean(0); sd=X[tr].std(0)+1e-6; Z=(X-mu)/sd/np.sqrt(X.shape[1])
            rng=np.random.default_rng(s)
            if sel=='random': Cc=Z[rng.choice(tr,nunits,replace=False)]
            elif sel=='piv': Cc=Z[tr][pivchol(Z[tr],f,nunits)]
            elif sel=='kmeans': Cc=kmeans(Z[tr],nunits,seed=s)
            H=f(Z,Cc); Kcc=f(Cc,Cc)
            T=np.eye(8)[y[tr]]-1/8; Ht=H[tr]; G=Ht.T@Ht; R=Ht.T@T
            for l in lams:
                B=np.linalg.solve(G+l*Kcc+1e-8*np.trace(G)/len(G)*np.eye(len(G)),R); res[l]+=((H[te]@B).argmax(1)==y[te]).sum()
    return {l:round(v/(n*len(seeds)),4) for l,v in res.items()}
